import requests, xml.etree.ElementTree as ET, json
pm='25073934'; root=ET.fromstring(requests.get(f'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pubmed&id={pm}&retmode=xml').text); art=root.find('.//PubmedArticle')
print('DOI', [x.text for x in art.findall('.//ArticleId') if x.attrib.get('IdType')=='doi'])
print('PMCID', [x.text for x in art.findall('.//ArticleId') if x.attrib.get('IdType')=='pmc'])
for url in [f'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=EXT_ID:{pm}&format=json',f'https://api.unpaywall.org/v2/{[x.text for x in art.findall(".//ArticleId") if x.attrib.get("IdType")=="doi"][0]}?email=test@example.com']:
 try:
  z=requests.get(url,timeout=20); print('\nURL',url,'STATUS',z.status_code); print(z.text[:3000])
 except Exception as e: print(e)
